A: Libra

 整数A, B, C, D を読み込み、A + B とC + D の大小比較をすればよいです。

#include <stdio . h>

 int main ()

{

          int  a , b ,  c , d ;

         scanf (”%d%d%d%d” , &a , &b , &c , &d ) ;

                  i f  ( a + b > c + d) p r i n t f (” Left \n ” ) ;

           e l s e    i f  ( a + b == c + d) p r i n t f (” Balanced\n ” ) ;

           e l s e  p r i n t f (” Right\n ” ) ;

}





